class _AdminAppState extends State<AdminApp> {
  late final AdminApi api = AdminApi(baseUrl: const String.fromEnvironment('API_BASE_URL'));
  bool signedIn = false;
  String username = '';
  int tab = 0;
  @override void initState() { super.initState(); _restore(); }
  Future<void> _restore() async { if (await api.token != null && mounted) { try { final me=await api.request('GET','/api/manager/me'); final role=((me['manager'] as Map?)?['role']??'').toString().toLowerCase(); if({'admin','superadmin'}.contains(role)){setState(()=>signedIn=true);return;} } catch (_) {} await api.signOut(); } }
  void _expired() { if (!mounted) return; setState(()=>signedIn=false); ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Session ended. Please sign in again.'))); }
  @override void dispose(){api.close();super.dispose();}
  @override Widget build(BuildContext context) => signedIn ? Scaffold(
    appBar: AppBar(title: const Text('Creatarsh Admin',style:TextStyle(fontWeight:FontWeight.w800)), backgroundColor:const Color(0xfff4faf6), actions:[IconButton(tooltip:'Refresh',onPressed:()=>setState((){}),icon:const Icon(Icons.refresh_rounded)),IconButton(tooltip:'Sign out',onPressed:()async{await api.signOut();if(mounted)setState(()=>signedIn=false);},icon:const Icon(Icons.logout_rounded))]),
    body: IndexedStack(index:tab,children:[_Overview(api:api,onExpired:_expired),_Businesses(api:api,onExpired:_expired),_Deployments(api:api,onExpired:_expired),_Moderation(api:api,onExpired:_expired),_Reports(api:api,onExpired:_expired)]),
    bottomNavigationBar:NavigationBar(selectedIndex:tab,onDestinationSelected:(v)=>setState(()=>tab=v),destinations:const [NavigationDestination(icon:Icon(Icons.dashboard_outlined),selectedIcon:Icon(Icons.dashboard),label:'Overview'),NavigationDestination(icon:Icon(Icons.storefront_outlined),label:'Businesses'),NavigationDestination(icon:Icon(Icons.rocket_launch_outlined),label:'Deployments'),NavigationDestination(icon:Icon(Icons.gavel_outlined),label:'Moderation'),NavigationDestination(icon:Icon(Icons.query_stats_outlined),label:'Reports')]),
  ) : _Login(api:api,onSignedIn:(name){setState((){signedIn=true;username=name;});});
}

