class _AsyncPanel<T> extends StatefulWidget {const _AsyncPanel({super.key,required this.load,required this.builder,required this.onExpired});final Future<T> Function() load;final Widget Function(T data) builder;final VoidCallback onExpired;@override State<_AsyncPanel<T>> createState()=>_AsyncPanelState<T>();}
